package jp.dare.watch;
import org.json.*;
import java.util.*;

/** Shared state operations matching the browser's version 2 schema. */
final class WatchModel {
 static String fullTableName(JSONObject s,String id){JSONArray floors=s.optJSONArray("floors");if(floors!=null)for(int i=0;i<floors.length();i++){JSONObject floor=floors.optJSONObject(i);JSONArray tables=floor.optJSONArray("tables");if(tables!=null)for(int j=0;j<tables.length();j++){JSONObject table=tables.optJSONObject(j);if(id.equals(table.optString("id")))return floor.optString("name")+"・"+table.optString("name");}}return "未設定";}
 static JSONObject cast(JSONObject s,String id){JSONArray a=s.optJSONArray("casts");if(a!=null)for(int i=0;i<a.length();i++){JSONObject c=a.optJSONObject(i);if(c!=null&&id.equals(c.optString("id")))return c;}return null;}
 static JSONObject timer(JSONObject s,String id){JSONObject a=s.optJSONObject("timers");return a==null?null:a.optJSONObject(id);}
 static long remaining(JSONObject t){return t==null?0:Math.max(0,t.optBoolean("paused")?t.optLong("pausedRemainingMs"):t.optLong("endsAt")-System.currentTimeMillis());}
 static String name(JSONObject s,String id){JSONArray floors=s.optJSONArray("floors");if(floors!=null)for(int i=0;i<floors.length();i++){JSONArray a=floors.optJSONObject(i).optJSONArray("tables");if(a!=null)for(int j=0;j<a.length();j++)if(id.equals(a.optJSONObject(j).optString("id")))return a.optJSONObject(j).optString("name");}return "未設定";}
 static String day(){Calendar c=Calendar.getInstance();c.add(Calendar.HOUR_OF_DAY,-6);return new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.JAPAN).format(c.getTime());}
 static JSONArray prepend(JSONArray a,JSONObject entry)throws Exception{JSONArray n=new JSONArray().put(entry);if(a!=null)for(int i=0;i<a.length();i++)n.put(a.get(i));return n;}
 static void selectTime(JSONObject s,String id,long ms,boolean record)throws Exception{
  JSONObject c=cast(s,id);if(c==null)return;long now=System.currentTimeMillis();
  WatchRepository.object(s,"timers").put(id,new JSONObject().put("durationMs",ms).put("startedAt",now).put("endsAt",now+ms).put("paused",true).put("pausedRemainingMs",ms).put("alerted",false).put("tableId",c.optString("currentTableId")));
  if(record)c.put("timerHistory",prepend(c.optJSONArray("timerHistory"),new JSONObject().put("id","timer-"+UUID.randomUUID()).put("tableId",c.optString("currentTableId")).put("tableName",name(s,c.optString("currentTableId"))).put("durationMs",ms).put("at",now)));
 }
 static void toggle(JSONObject s,String id)throws Exception{JSONObject t=timer(s,id);if(t==null){selectTime(s,id,300000,true);t=timer(s,id);}if(t.optBoolean("paused")){long ms=remaining(t);if(ms==0)ms=t.optLong("durationMs",300000);t.put("endsAt",System.currentTimeMillis()+ms).put("startedAt",System.currentTimeMillis()).put("paused",false).put("alerted",false);t.remove("pausedRemainingMs");}else{t.put("pausedRemainingMs",remaining(t)).put("paused",true);}}
 static void adjust(JSONObject s,String id,long delta)throws Exception{JSONObject t=timer(s,id);if(t==null)return;long ms=Math.max(0,remaining(t)+delta);if(t.optBoolean("paused"))t.put("pausedRemainingMs",ms);else t.put("endsAt",System.currentTimeMillis()+ms);t.put("durationMs",Math.max(1000,t.optLong("durationMs")+delta)).put("alerted",false);}
 static long duration(JSONObject c,String table,long fallback){JSONArray a=c.optJSONArray("timerHistory");if(a!=null)for(int i=0;i<a.length();i++)if(table.equals(a.optJSONObject(i).optString("tableId")))return a.optJSONObject(i).optLong("durationMs",fallback);return fallback;}
 static void move(JSONObject s,String id)throws Exception{JSONObject c=cast(s,id);if(c==null)return;String from=c.optString("currentTableId"),to=c.optString("destinationTableId");JSONArray route=c.optJSONArray("nominatedTableIds");if(route==null||route.length()<2||to.isEmpty()||to.equals("null")||to.equals(from))return;
  long now=System.currentTimeMillis(),ms=duration(c,to,duration(c,from,timer(s,id)==null?300000:timer(s,id).optLong("durationMs",300000)));
  JSONObject before=new JSONObject().put("timer",timer(s,id)==null?JSONObject.NULL:new JSONObject(timer(s,id).toString())).put("nextTableId",c.opt("nextTableId")).put("destinationTableId",c.opt("destinationTableId"));WatchRepository.array(c,"undoStack").put(new JSONObject().put("fromTableId",from).put("toTableId",to).put("at",now).put("before",before));
  c.put("history",prepend(c.optJSONArray("history"),new JSONObject().put("fromTableId",from).put("fromTableName",name(s,from)).put("toTableId",to).put("toTableName",name(s,to)).put("at",now).put("reason","卓移動")));
  c.put("currentTableId",to);for(int i=0;i<route.length();i++)if(to.equals(route.optString(i))){String next=route.optString((i+1)%route.length());c.put("nextTableId",next).put("destinationTableId",next);break;}selectTime(s,id,ms,true);
 }
 static void undo(JSONObject s,String id)throws Exception{JSONObject c=cast(s,id);if(c==null)return;JSONArray a=c.optJSONArray("undoStack");if(a==null||a.length()==0)return;JSONObject entry=a.getJSONObject(a.length()-1);if(!c.optString("currentTableId").equals(entry.optString("toTableId")))return;a.remove(a.length()-1);String from=c.optString("currentTableId"),to=entry.optString("fromTableId");c.put("currentTableId",to).put("nextTableId",from).put("destinationTableId",from);JSONObject before=entry.optJSONObject("before");if(before!=null){if(before.isNull("timer"))WatchRepository.object(s,"timers").remove(id);else WatchRepository.object(s,"timers").put(id,new JSONObject(before.getJSONObject("timer").toString()));c.put("nextTableId",before.opt("nextTableId")).put("destinationTableId",before.opt("destinationTableId"));}else selectTime(s,id,duration(c,to,300000),false);c.put("history",prepend(c.optJSONArray("history"),new JSONObject().put("fromTableId",from).put("fromTableName",name(s,from)).put("toTableId",to).put("toTableName",name(s,to)).put("at",System.currentTimeMillis()).put("reason","移動取り消し")));}
 static void remove(JSONObject s,String id)throws Exception{JSONArray a=WatchRepository.array(s,"casts");for(int i=a.length()-1;i>=0;i--)if(id.equals(a.optJSONObject(i).optString("id")))a.remove(i);WatchRepository.object(s,"timers").remove(id);}
 static boolean expired(JSONObject s){JSONArray a=s.optJSONArray("casts");if(a!=null)for(int i=0;i<a.length();i++){JSONObject c=a.optJSONObject(i);if(c.optBoolean("dayAdded")&&!day().equals(c.optString("dayAddedOn")))return true;}return false;}
 static void rollover(JSONObject s)throws Exception{JSONArray a=WatchRepository.array(s,"casts");for(int i=a.length()-1;i>=0;i--){JSONObject c=a.getJSONObject(i);if(!c.optBoolean("dayAdded")||day().equals(c.optString("dayAddedOn")))continue;WatchRepository.array(s,"dayMemberHistory").put(new JSONObject().put("castId",c.optString("id")).put("name",c.optString("name")).put("date",c.optString("dayAddedOn")).put("movementHistory",c.optJSONArray("history")).put("timerHistory",c.optJSONArray("timerHistory")).put("archivedAt",System.currentTimeMillis()));remove(s,c.optString("id"));}}
}

